<?php
declare(strict_types=1);require '../config/db.php';require '../config/auth.php';require_role('admin','login.php');
$id=(int)($_GET['id']??0);
$s=$pdo->prepare("SELECT a.reference_no,a.appointment_date,a.start_time,a.end_time,a.status,u.full_name parishioner,s.name service_name,w.* FROM appointments a JOIN users u ON u.id=a.user_id JOIN services s ON s.id=a.service_id LEFT JOIN wedding_booking_details w ON w.appointment_id=a.id WHERE a.id=? AND LOWER(s.name)='wedding'");$s->execute([$id]);$w=$s->fetch();if(!$w){http_response_code(404);exit('Wedding booking details not found. Run database/migrate_wedding_booking.sql if this is an older booking.');}
function age_from_dob(?string $d):string{if(!$d)return '—';return (string)(new DateTime($d))->diff(new DateTime('today'))->y;}
$docs=['PSA Birth Certificates'=>'psa_birth_certificates','PSA CENOMAR'=>'cenomar','Baptism & Confirmation'=>'baptism_confirmation','PMC Certificate'=>'pmc_certificate','Marriage document'=>'marriage_document'];
function wedding_doc_paths(?string $value): array { if(!$value)return []; $decoded=json_decode($value,true); if(is_array($decoded))return array_values(array_filter($decoded,'is_string')); return [$value]; }
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wedding Details</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="shell"><?php include 'includes/sidebar.php'?><main class="main"><header class="topbar"><div><div class="eyebrow"><?=e($w['reference_no'])?></div><h1>Wedding booking details.</h1></div></header><section class="grid two"><div class="card"><h2>Couple details</h2><div class="grid two"><div><small class="muted">Groom</small><p><b><?=e($w['groom_full_name'])?></b><br><?=e($w['groom_dob'])?> · Age <?=e(age_from_dob($w['groom_dob']))?><br><?=e($w['groom_religion_parish'])?></p></div><div><small class="muted">Bride</small><p><b><?=e($w['bride_full_name'])?></b><br><?=e($w['bride_dob'])?> · Age <?=e(age_from_dob($w['bride_dob']))?><br><?=e($w['bride_religion_parish'])?></p></div></div><small class="muted">Primary contact</small><p><?=e($w['contact_number'])?> · <?=e($w['contact_email'])?></p></div><div class="card"><h2>Ceremony & schedule</h2><small class="muted">Ceremony type</small><p><b><?=e($w['ceremony_type'])?></b></p><small class="muted">Schedule</small><p><?=date('F j, Y',strtotime($w['appointment_date']))?> · <?=date('g:i A',strtotime($w['start_time']))?>–<?=date('g:i A',strtotime($w['end_time']))?></p><small class="muted">Preferred officiant</small><p><?=e($w['preferred_officiant']?:'No preference')?></p><small class="muted">Civil requirement</small><p><?=e($w['civil_requirement']==='contract'?'Civil Marriage Contract':'Civil Marriage License / Notice')?></p></div></section><section class="card" style="margin-top:18px"><h2>Submitted requirements</h2><div class="grid two"><?php foreach($docs as $label=>$field): $paths=wedding_doc_paths($w[$field]??null);?><div><small class="muted"><?=e($label)?></small><p><?php if($paths):?><?php foreach($paths as $i=>$path):?><a class="btn light small" target="_blank" href="../<?=e($path)?>">Open document <?=$i+1?></a> <?php endforeach?><?php else:?><span class="muted">Not uploaded yet</span><?php endif?></p></div><?php endforeach?></div><div class="notice">Documents may be completed after the initial request, but should be submitted at least 30 days before the wedding date.</div><div class="actions"><a class="btn light" href="appointments.php">← Back to appointments</a></div></section></main></div><script src="../assets/js/script.js"></script></body></html>
